INSERT INTO public.questions (id, question_version, bank_number, exam_year, exam_day, area, discipline, official_answer, answer_english, answer_spanish, source_file, source_type, is_official, status, is_annulled, raw_extract) VALUES ('ENEM2025-Q010','ENEM-2025',10,2025,1,'LC','Linguagens','E','E',NULL,'2025_PV_impresso_D1_CD1.pdf','OFFICIAL_ENEM',true,'RAW_EXTRACT',false,'Questão 10 O recurso linguístico usado para marcar a síntese da opinião da autora sobre a temática desenvolvida foi o(a) A emprego da primeira pessoa em “Estranhei muito na primeira vez que escutei a expressão ‘de próprio punho’”. (l. 1) B utilização de locução adverbial em “Na verdade, o que importava era a autenticidade da minha caligrafia”. (l. 3-4) C uso de pronome possessivo em “Minha letra, hoje, tem uma espécie de alternância”. (l. 5-6) D adoção de termo autorreflexivo em “No escritório, costumo ser mais suave comigo mesma”. (l. 30) E substituição da expressão “Do punho ao pixel” (l. 44) pela expressão “o punho e o pixel”. (l. 45)  LINGUAGENS, CÓDIGOS E SUAS TECNOLOGIAS E REDAÇÃO | 1º DIA | CADERNO 1 | AZUL 7 010175AZ.indb 7 23/07/2025 12:32:06 *010175AZ8*  Questão 11 Questão 13 — Vejo, disse ele com algum acanhamento, que o doutor não Art. 26-A. Nos estabelecimentos de ensino fundamental é nenhum pé-rapado, mas nunca é bom facilitar... Minha filha e médio, oficiais e particulares, torna-se obrigatório o ensino Nocência fez 18 anos pelo Natal, e é rapariga que pela feição parece ') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, question_version, bank_number, exam_year, exam_day, area, discipline, official_answer, answer_english, answer_spanish, source_file, source_type, is_official, status, is_annulled, raw_extract) VALUES ('ENEM2025-Q011','ENEM-2025',11,2025,1,'LC','Linguagens','B','B',NULL,'2025_PV_impresso_D1_CD1.pdf','OFFICIAL_ENEM',true,'RAW_EXTRACT',false,'Questão 11 Questão 13 — Vejo, disse ele com algum acanhamento, que o doutor não Art. 26-A. Nos estabelecimentos de ensino fundamental é nenhum pé-rapado, mas nunca é bom facilitar... Minha filha e médio, oficiais e particulares, torna-se obrigatório o ensino Nocência fez 18 anos pelo Natal, e é rapariga que pela feição parece sobre História e Cultura Afro-Brasileira. moça de cidade, muito ariscazinha de modos, mas bonita e boa § 1º O conteúdo programático a que se refere o caput deste deveras... Coitada, foi criada sem mãe, e aqui nestes fundões. [...] artigo incluirá o estudo da História da África e dos Africanos, a luta — Ora muito que bem, continuou Pereira caindo aos poucos dos negros no Brasil, a cultura negra brasileira e o negro na formação na habitual garrulice, quando vi a menina tomar corpo, tratei logo de casá-la. da sociedade nacional, resgatando a contribuição do povo negro nas áreas social, econômica e política pertinentes à História do Brasil. — Ah! é casada? perguntou Cirino. — Isto é, é e não é. A coisa está apalavrada. Por aqui costuma § 2º Os conteúdos referentes à História e Cultura Afro- labutar ') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, question_version, bank_number, exam_year, exam_day, area, discipline, official_answer, answer_english, answer_spanish, source_file, source_type, is_official, status, is_annulled, raw_extract) VALUES ('ENEM2025-Q012','ENEM-2025',12,2025,1,'LC','Linguagens','C','C',NULL,'2025_PV_impresso_D1_CD1.pdf','OFFICIAL_ENEM',true,'RAW_EXTRACT',false,'Questão 12 O Ministério do Esporte no Brasil lançou o programa Maré Inclusiva, em 2024, ano dos Jogos Paralímpicos de Paris. Esse programa visa ampliar as oportunidades para pessoas com deficiência que desejam praticar o surf. O parasurf é a prática do surf adaptada para permitir que pessoas com deficiência pratiquem o esporte em todas as suas categorias, modalidades e manifestações. Para a Secretaria Nacional do Paradesporto, a iniciativa é mais do que um programa de esporte, é uma iniciativa que busca transformar vidas e promover a inclusão por meio do parasurf, criando um legado de igualdade e respeito. Disponível em: www.gov.br/esporte. Acesso em: 6 set. 2024 (adaptado). Disponível em: www.publishnews.com.br. Acesso em: 19 set. 2024. De acordo com esse texto, o programa voltado ao estímulo da Nesse cartaz publicitário, os recursos verbais e não verbais prática do parasurf evidencia a constroem um argumento que objetiva A adesão de diferentes países a programas inclusivos. A divulgar a obra de Fernando Pessoa no Brasil. B preocupação política em atender a demandas paralímpicas. C importância de uma política pública esportiva para a inclusão. B valorizar a realização de eventos literários no país. D eficiência das iniciativas de inclusão em megaeventos esportivos. C ressaltar o impacto da leitura na vida das pessoas. E escassez de investimento em práticas corporais de aventura D fomentar o turismo cultural na cidade de São Paulo. na natureza. E evidenciar a in') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, question_version, bank_number, exam_year, exam_day, area, discipline, official_answer, answer_english, answer_spanish, source_file, source_type, is_official, status, is_annulled, raw_extract) VALUES ('ENEM2025-Q013','ENEM-2025',13,2025,1,'LC','Linguagens','E','E',NULL,'2025_PV_impresso_D1_CD1.pdf','OFFICIAL_ENEM',true,'RAW_EXTRACT',false,'Questão 13 — Vejo, disse ele com algum acanhamento, que o doutor não Art. 26-A. Nos estabelecimentos de ensino fundamental é nenhum pé-rapado, mas nunca é bom facilitar... Minha filha e médio, oficiais e particulares, torna-se obrigatório o ensino Nocência fez 18 anos pelo Natal, e é rapariga que pela feição parece sobre História e Cultura Afro-Brasileira. moça de cidade, muito ariscazinha de modos, mas bonita e boa § 1º O conteúdo programático a que se refere o caput deste deveras... Coitada, foi criada sem mãe, e aqui nestes fundões. [...] artigo incluirá o estudo da História da África e dos Africanos, a luta — Ora muito que bem, continuou Pereira caindo aos poucos dos negros no Brasil, a cultura negra brasileira e o negro na formação na habitual garrulice, quando vi a menina tomar corpo, tratei logo de casá-la. da sociedade nacional, resgatando a contribuição do povo negro nas áreas social, econômica e política pertinentes à História do Brasil. — Ah! é casada? perguntou Cirino. — Isto é, é e não é. A coisa está apalavrada. Por aqui costuma § 2º Os conteúdos referentes à História e Cultura Afro- labutar no costeio do gado para São Paulo um homem de mão- -Brasile') ON CONFLICT DO NOTHING;
