INSERT INTO public.questions (id, question_version, bank_number, exam_year, exam_day, area, discipline, official_answer, answer_english, answer_spanish, source_file, source_type, is_official, status, is_annulled, raw_extract) VALUES ('ENEM2025-Q022','ENEM-2025',22,2025,1,'LC','Linguagens','B','B',NULL,'2025_PV_impresso_D1_CD1.pdf','OFFICIAL_ENEM',true,'RAW_EXTRACT',false,'Questão 22 Questão 23 TEXTO I TEXTO I A Ilha do Ferro, situada a 18 km do município de Pão de Os trabalhos da exposição Adriana Varejão: suturas, fissuras, Açúcar, não é uma ilha, como o nome indica. A história do ruínas colocam em pauta o exame da história visual, das tradições povoado é semelhante à de inúmeros outros que encontramos iconográficas europeias e do fazer artístico ocidental. O corte, às margens do Rio São Francisco, entre Alagoas e Sergipe. O que a rachadura, o talho e a fissura são elementos de narrativas torna diferente o lugar é sua gente. Hoje, dezenas de artistas recorrentes nos trabalhos da artista desde 1992. As produções populares povoam a Ilha do Ferro, trabalhando principalmente recentes incluem pinturas tridimensionais de grande escala das com o entalhe em madeira. Onde pessoas comuns enxergariam séries Ruínas de charque e Línguas. apenas troncos e galhos retorcidos, eles vislumbram bancos, Disponível em: https://pinacoteca.org.br. ') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, question_version, bank_number, exam_year, exam_day, area, discipline, official_answer, answer_english, answer_spanish, source_file, source_type, is_official, status, is_annulled, raw_extract) VALUES ('ENEM2025-Q023','ENEM-2025',23,2025,1,'LC','Linguagens','C','C',NULL,'2025_PV_impresso_D1_CD1.pdf','OFFICIAL_ENEM',true,'RAW_EXTRACT',false,'Questão 23 TEXTO I TEXTO I A Ilha do Ferro, situada a 18 km do município de Pão de Os trabalhos da exposição Adriana Varejão: suturas, fissuras, Açúcar, não é uma ilha, como o nome indica. A história do ruínas colocam em pauta o exame da história visual, das tradições povoado é semelhante à de inúmeros outros que encontramos iconográficas europeias e do fazer artístico ocidental. O corte, às margens do Rio São Francisco, entre Alagoas e Sergipe. O que a rachadura, o talho e a fissura são elementos de narrativas torna diferente o lugar é sua gente. Hoje, dezenas de artistas recorrentes nos trabalhos da artista desde 1992. As produções populares povoam a Ilha do Ferro, trabalhando principalmente recentes incluem pinturas tridimensionais de grande escala das com o entalhe em madeira. Onde pessoas comuns enxergariam séries Ruínas de charque e Línguas. apenas troncos e galhos retorcidos, eles vislumbram bancos, Disponível em: https://pinacoteca.org.br. Acesso em: 10 jan. 2025 (adaptado). bonecos, pássaros, cobras e bailarinas. “Às vezes, você passa por um pedaço de madeira uma vez e não vê nada, passa cinco ') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, question_version, bank_number, exam_year, exam_day, area, discipline, official_answer, answer_english, answer_spanish, source_file, source_type, is_official, status, is_annulled, raw_extract) VALUES ('ENEM2025-Q024','ENEM-2025',24,2025,1,'LC','Linguagens','B','B',NULL,'2025_PV_impresso_D1_CD1.pdf','OFFICIAL_ENEM',true,'RAW_EXTRACT',false,'Questão 24 Disponível em: www.unicef.org.br. Acesso em: 15 jan. 2024 (adaptado). Nesse cartaz, a utilização de frases que projetam a vida profissional de duas crianças tem como objetivo A sugerir a arrecadação de fundos para o sustento de povos originários no país. B sensibilizar a sociedade sobre os benefícios decorrentes do combate ao racismo. C indicar a importância da orientação vocacional na educação de crianças no Brasil. D chamar a atenção sobre a necessidade de ações voltadas para a educação infantil. E valorizar o trabalho de agências internacionais na luta contra a discriminação racial. Questão 25 Passando por aqui para lembrar algumas palavras, frases e expressões que nos infernizaram em 2023. Inclusive passando por aqui. Se você for proativo, vai achar que é o novo normal. Estarão na sua zona de conforto. Mas, se for reativo como eu, vai achar que é uma narrativa que precisa ser ressignificada. É uma questão de empatia. É sobre entregar um discurso mais robusto e empoderado. Sei bem que não tenho lugar de fala para harmonizar certos pontos fora da curva e que preciso aplicar toda a minha resiliência para fazer um realinhamento. O nível de fitness está hoje num sarrafo muito alto. O fato é que acho cringe essas falas fora da caixinha. Aliás, falar cringe já é meio cringe. Preciso usar a superação para me reinventar e entender que resenha não tem mais a ver com futebol, é qualquer papo, desde que latente. Pensando bem, não é tão difícil. Frases feitas são aquelas que entram por um ouvido e saem pelo outro sem um estágio intermediário no cérebro. A boca fala por conta própria, dispensando-nos de pensar. E não tem problema nisso. Ou as ditas frases se incorporam à língua ou morrem e nascem outras. A língua é assim. Simples assim. CASTRO, R. Disponível em: www1.folha.uol.com.br. Acesso em: 3 fev. 2024 (adaptado). Nesse texto, a estratégia empregada para criticar a constante exposição a palavras, frases e expressões automatizadas é o(a) A menção feita à efemeridade de alguns usos linguísticos aleatórios. B subjetividade marcada pela reflexão que se desenvolve em primeira pessoa. C efeito estilístico da repetição intencional da palavra “assim” no último parágrafo. D sedução sugerida pelo envolvimento direto do leitor marcado nos usos de “você” e “sua”. E humor gerado pelo uso das estruturas linguísticas que são objeto da reflexão desenvolvida. ENEM2025ENEM2025ENEM2025ENEM2025ENEM2025ENEM2025ENEM2025ENEM2025ENEM2025ENEM2025ENEM2025ENEM2025ENEM2025ENEN2') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, question_version, bank_number, exam_year, exam_day, area, discipline, official_answer, answer_english, answer_spanish, source_file, source_type, is_official, status, is_annulled, raw_extract) VALUES ('ENEM2025-Q025','ENEM-2025',25,2025,1,'LC','Linguagens','E','E',NULL,'2025_PV_impresso_D1_CD1.pdf','OFFICIAL_ENEM',true,'RAW_EXTRACT',false,'Questão 25 Passando por aqui para lembrar algumas palavras, frases e expressões que nos infernizaram em 2023. Inclusive passando por aqui. Se você for proativo, vai achar que é o novo normal. Estarão na sua zona de conforto. Mas, se for reativo como eu, vai achar que é uma narrativa que precisa ser ressignificada. É uma questão de empatia. É sobre entregar um discurso mais robusto e empoderado. Sei bem que não tenho lugar de fala para harmonizar certos pontos fora da curva e que preciso aplicar toda a minha resiliência para fazer um realinhamento. O nível de fitness está hoje num sarrafo muito alto. O fato é que acho cringe essas falas fora da caixinha. Aliás, falar cringe já é meio cringe. Preciso usar a superação para me reinventar e entender que resenha não tem mais a ver com futebol, é qualquer papo, desde que latente. Pensando bem, não é tão difícil. Frases feitas são aquelas que entram por um ouvido e saem pelo outro sem um estágio intermediário no cérebro. A boca fala por conta própria, dispensando-nos de pensar. E não tem problema nisso. Ou as ditas frases se incorporam à língua ou morrem e nascem outras. A língua é assim. Simples assim. CASTRO, R. Disponível em: www1.folha.uol.com.br. Acesso em: 3 fev. 2024 (adaptado). Nesse texto, a estratégia empregada para criticar a constante exposição a palavras, frases e expressões automatizadas é o(a) A menção feita à efemeridade de alguns usos linguísticos aleatórios. B subjetividade marcada pela reflexão que se desenvolve em primeira pessoa. C efeito estilístico da repetição intencional da palavra “assim” no último parágrafo. D sedução sugerida pelo envolvimento direto do leitor marcado nos usos de “você” e “sua”. E humor gerado pelo uso das estruturas linguísticas que são objeto da reflexão desenvolvida.  12 LINGUAGENS, CÓDIGOS E SUAS TECNOLOGIAS E REDAÇÃO | 1º DIA | CADERNO 1 | AZUL 010175AZ.indb 12 23/07/2025 12:32:13 ') ON CONFLICT DO NOTHING;
