INSERT INTO public.questions (id, question_version, bank_number, exam_year, exam_day, area, discipline, official_answer, answer_english, answer_spanish, source_file, source_type, is_official, status, is_annulled, raw_extract) VALUES ('ENEM2025-Q027','ENEM-2025',27,2025,1,'LC','Linguagens','A','A',NULL,'2025_PV_impresso_D1_CD1.pdf','OFFICIAL_ENEM',true,'RAW_EXTRACT',false,'Questão 27 princesas, bobos da corte, cortesãos, conselheiros e escravos, A diferença entre briga e luta é a existência de juízes e medalhas? muitos escravos. […] A briga desumaniza o outro e pode até matá-lo. Já na luta, as A corte do massapé, como qualquer outra na história da intenções do outro são consideradas sua proposta combativa e suas humanidade, fazia tudo para não deixar escapar nenhum mísero habilidades, enfim, sua meta de vencer. Na luta, o desenvolvimento grão dos seus domínios para quem estivesse de fora do seu passa pelo contato com a agressividade, a raiva, a frustração, o apertado círculo. Os nomes se repetiam de pai para filho, para orgulho, a determinação e a fraqueza. Daí também a luta não ser apenas com o outro, mas consigo mesmo, num combate contra as sobrinho, para netos e bisnetos, de forma concêntrica e repetitiva, próprias limitações, sobretudo, contra o próprio orgulho. para que não pairasse nenhuma dúvida de que são todos da BARREIRA, C. A briga desumaniza. A luta, não. mesma parentela. As farinhas todas num mesmo saco brasonado. O Estado de S. Paulo, 22 ago. 2010 (adaptado). CRUZ, E') ON CONFLICT DO NOTHING;
