INSERT INTO public.questions (id, question_version, bank_number, exam_year, exam_day, area, discipline, official_answer, answer_english, answer_spanish, source_file, source_type, is_official, status, is_annulled, raw_extract) VALUES ('ENEM2025-Q046','ENEM-2025',46,2025,1,'CH','Ciências Humanas','E','E',NULL,'2025_PV_impresso_D1_CD1.pdf','OFFICIAL_ENEM',true,'RAW_EXTRACT',false,'Questão 46 Macedônia do Norte Acordo entra em vigor e país muda oficialmente de nome Entrou em vigor, em 2019, o acordo que determina a mudança de nome da Macedônia para Macedônia do Norte. A troca põe fim — ao menos por enquanto — no impasse entre essa antiga república da Iugoslávia e a vizinha Grécia. O governo grego se opunha ao uso do nome Macedônia pelo novo país vizinho porque a Grécia tem uma província no norte com o mesmo nome. Por causa desse impasse, a Grécia bloqueou as negociações de adesão de seu vizinho à União Europeia. Depois de negociações, as duas partes chegaram a um acordo. Disponível em: https://g1.globo.com. Acesso em: 7 nov. 2021 (adaptado). Para o país originado da antiga Iugoslávia, a mudança de nome é uma estratégia política para A criar a moeda própria. B proteger a cultura local. C subjugar a minoria étnica. D expandir o território nacional. E intensificar a integração regional. Questão 47 Concentração de CO2 por queimadas entre África e Brasil em 30 de agosto de 2019 Disponível em: https://noticias.uol.com.br. Acesso em: 10 out. 2019 (adaptado). A dispersão espacial do problema ambiental representado na imagem de satélite é explicada pela seguinte característica geográfica: A Amplitude das temperaturas médias. B Homogeneidade da insolação anual. C Ocorrência de chuvas de relevo. D Circulação de massas de ar. E Ausência de frentes frias. Questão 48 A credulidade dos ouvintes aumenta o descaramento do narrador, e o descaramento deste conquista-lhes a credulidade. A eloquência, quando levada a seu patamar mais alto, deixa pouco lugar à razão ou à reflexão, mas, dirigindo-se inteiramente à imaginação e aos afetos, cativa os ouvintes condescendentes e subjuga-lhes o entendimento. HUME, D. Uma investigação sobre o entendimento humano e sobre os princípios da moral. São Paulo: Edunesp, 2003. No contexto do século XVIII, o autor propõe uma reflexão radical acerca da arte da eloquência, restringindo-a ao A sistema de crenças, conforme a proposta kantiana de objetividade do conhecimento. B campo dos absolutos, semelhante ao entendimento medieval dos Universais. C domínio da lógica, consoante a compreensão aristotélica nos Analíticos. D paradigma da racionalidade, alinhado ao modelo cartesiano de método. ') ON CONFLICT DO NOTHING;
