INSERT INTO public.questions (id, question_version, bank_number, exam_year, exam_day, area, discipline, official_answer, answer_english, answer_spanish, source_file, source_type, is_official, status, is_annulled, raw_extract) VALUES ('ENEM2025-Q053','ENEM-2025',53,2025,1,'CH','Ciências Humanas','E','E',NULL,'2025_PV_impresso_D1_CD1.pdf','OFFICIAL_ENEM',true,'RAW_EXTRACT',false,'Questão 53 A “invenção” dessa nova anatomia política não deve ser entendida como uma descoberta súbita. Mas como uma TEXTO I multiplicidade de processos muitas vezes mínimos, de origens A partir do século IV, com os imperadores ditos cristãos, diferentes, de localizações esparsas, que se recordam, que se o teatro e a dança foram condenados. O batismo era recusado aos repetem, ou se imitam, apoiam-se uns sobre os outros e esboçam que atuavam no circo ou na pantomima. E em 398, no Concílio de aos poucos a fachada de um método geral. Encontramo-los Cartago, os que iam ao teatro nos dias santos foram excomungados. em funcionamento nos colégios, muito cedo; mais tarde, nas escolas primárias, no espaço hospitalar e na organização militar. DINIZ, T.; SANTOS, G. História da dança. Disponível em: www.uel.br. Acesso em: 18 out. 2023. FOUCAULT, M. Vigiar e punir. Petrópolis: Vozes, 2011. TEXTO II O texto indica o seguinte aspecto da disciplina como ferramenta A dança no ato litúrgico cumpre tanto um papel de adoração ') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, question_version, bank_number, exam_year, exam_day, area, discipline, official_answer, answer_english, answer_spanish, source_file, source_type, is_official, status, is_annulled, raw_extract) VALUES ('ENEM2025-Q054','ENEM-2025',54,2025,1,'CH','Ciências Humanas','E','E',NULL,'2025_PV_impresso_D1_CD1.pdf','OFFICIAL_ENEM',true,'RAW_EXTRACT',false,'Questão 54 Não há consenso em torno do nome dado à pandemia, A ideia de êxodo urbano assume ares caricaturais. Pega a mais tendo, desde o seu início, sido chamada de gripe espanhola reduzida parte da pirâmide social e projeta para todos seus desejos provavelmente por causa da desinformação em torno da notícia defensivos. Se o êxodo urbano for compreendido como aquisição de uma segunda residência, então não estamos, de fato, falando sobre sua origem. Uma das hipóteses deriva da neutralidade de êxodo, mas da reversão de um excedente de renda de uma espanhola na Primeira Guerra Mundial e a consequente pequena fração da elite para as franjas metropolitanas. Se o êxodo liberdade de imprensa naquele país, maior do que nos demais urbano for compreendido como retorno aos municípios menos países envolvidos no conflito. Hoje existe o consenso entre povoados, então não estamos, de fato, falando de êxodo urbano, virologistas e epidemiologistas de que o vírus da gripe não se mas de um movimento de migração de pessoas cuja estabilidade originou na Espanha. Entretanto, dificilmente essa pandemia no emprego e a elevada renda lhes permitem simular, nas ilhas deixará de ser conhecida como gripe espanhola. ') ON CONFLICT DO NOTHING;
