INSERT INTO public.questions (id, question_version, bank_number, exam_year, exam_day, area, discipline, official_answer, answer_english, answer_spanish, source_file, source_type, is_official, status, is_annulled, raw_extract) VALUES ('ENEM2025-Q070','ENEM-2025',70,2025,1,'CH','Ciências Humanas','B','B',NULL,'2025_PV_impresso_D1_CD1.pdf','OFFICIAL_ENEM',true,'RAW_EXTRACT',false,'Questão 70 Questão 73 Nos Estados Unidos, um hotel perto de um parque foi engolido Entre esses preconceitos estava o canibalismo. A prática não por uma enorme cratera. E não é a primeira vez que esse tipo era, porém, uma mentira, uma invenção europeia, mas um ritual de incidente acontece na Flórida. Em minutos, uma ala inteira controlado por regras. Entre os tupis, por exemplo, os guerreiros do hotel era engolida pela cratera de 30 metros de diâmetro e se sentiam honrados quando morriam em um banquete canibal. cinco de profundidade. O diretor do resort em Clermont, perto Para os europeus, no entanto, comer carne humana era dos parques temáticos da Flórida, diz que o prédio tinha 15 anos, e que até então o solo nunca havia apresentado problemas. abominável, pois nem mesmo os leões ingeriam seus semelhantes. Os afundamentos são um fenômeno comum na Flórida por Portanto, para os conquistadores, o canibalismo era sinônimo de causa das formações de calcário e argila no subsolo, mas às vezes barbarismo e da incapacidade de se autogovernar. chuvas fortes, ou a drenagem do solo para construção, acabam RAMINELLI, R. Canibalismo para alemão ver. In: FIGUEIREDO, L. (Org.). contribuindo para o surgimento desses buracos. ') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, question_version, bank_number, exam_year, exam_day, area, discipline, official_answer, answer_english, answer_spanish, source_file, source_type, is_official, status, is_annulled, raw_extract) VALUES ('ENEM2025-Q071','ENEM-2025',71,2025,1,'CH','Ciências Humanas','A','A',NULL,'2025_PV_impresso_D1_CD1.pdf','OFFICIAL_ENEM',true,'RAW_EXTRACT',false,'Questão 71 Questão 74 Moradores de Berlim protestaram contra a demolição de um trecho do muro que dividiu a cidade durante quase três Fragmentada em pequenos grupos, fragilizada pela ausência décadas. Tratado como patrimônio cultural e histórico da cidade, de algum tipo de organização ampla, tendo que carregar o East Side Gallery, repleto de grafites emblemáticos, está na o peso do preconceito racial que se transfere do negro para a mira de uma construtora que pretende levantar um condomínio cultura negra, a religião dos orixás tem poucas chances de se de luxo às margens do Rio Spree, que corta a cidade. sair melhor na competição — desigual — com outras religiões. ALMEIDA, R. Alemães impedem demolição de último trecho original do Silenciosamente, assistimos hoje a um verdadeiro massacre das muro de Berlim. Disponível em: http://operamundi.uol.com.br. religiões afro-brasileiras. Acesso em: 2 fev. 2021 (adaptado). PRANDI, R. O Brasil com axé. Estudos Avançados, n. 52, dez. 2004. A demolição do símbolo histórico mencionado representa uma No processo de invisibilização dos cultos afro-brasileiros, o texto A violação da memória coletiva. ') ON CONFLICT DO NOTHING;
