INSERT INTO public.questions (id, question_version, bank_number, exam_year, exam_day, area, discipline, official_answer, answer_english, answer_spanish, source_file, source_type, is_official, status, is_annulled, raw_extract) VALUES ('ENEM2025-Q075','ENEM-2025',75,2025,1,'CH','Ciências Humanas','B','B',NULL,'2025_PV_impresso_D1_CD1.pdf','OFFICIAL_ENEM',true,'RAW_EXTRACT',false,'Questão 75 consonância e em dissonância. De todos um e de um todos. A partir do século XIX e, principalmente, no século XX, iniciou-se (Fragmento B10) o uso de produtos sintéticos na agricultura. No Brasil, a partir da TEXTO II década de 1960 e, posteriormente, nos anos 1970, os inseticidas Deus é dia-noite, inverno-verão, guerra-paz, saciedade-fome. ampliam sua fatia no mercado dos defensivos agrícolas. (Fragmento B67) TROPPMAIR, H. Biogeografia e meio ambiente. Pré-socráticos. São Paulo: Nova Cultural, 1996. Rio de Janeiro: TB, 2012 (adaptado). A característica do pensamento do filósofo Heráclito, registrada Nos espaços agrícolas, a mudança técnica descrita provocou nos fragmentos mencionados, é a ênfase na a diminuição da A qualidade imperecível do mundo. A desagregação de camadas pedológicas. B degradação material da natureza. B diversidade de polinizadores naturais. C imobilidade imanente do universo. ') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, question_version, bank_number, exam_year, exam_day, area, discipline, official_answer, answer_english, answer_spanish, source_file, source_type, is_official, status, is_annulled, raw_extract) VALUES ('ENEM2025-Q076','ENEM-2025',76,2025,1,'CH','Ciências Humanas','C','C',NULL,'2025_PV_impresso_D1_CD1.pdf','OFFICIAL_ENEM',true,'RAW_EXTRACT',false,'Questão 76 Questão 78 Os direitos do homem constituem uma classe variável, como A Roda dos Expostos de Salvador (Bahia) data de 1726 e a história destes últimos séculos demonstra suficientemente. foi uma das instituições implantadas com o objetivo de acolher O elenco dos direitos do homem se modificou, e continua a se e prover um encaminhamento para a criança recém-nascida modificar, com a mudança das condições históricas, ou seja, abandonada. Essa assistência fundamentava-se em práticas dos carecimentos e dos interesses, das classes no poder, dos meios caritativas, paternalistas e imediatistas que visavam ao cuidado disponíveis para a realização dos mesmos, das transformações básico da criança e, especialmente, à salvação da sua alma, técnicas. Direitos que foram declarados absolutos no final do via batismo, devido à alta mortalidade. século XVIII foram submetidos a radicais limitações nas declarações BORRIONE, R.; CHAVES, A. M. Análise documental e contexto de desenvolvimento. Disponível em: www.scielo.br. contemporâneas; direitos que as declarações do século XVIII ') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, question_version, bank_number, exam_year, exam_day, area, discipline, official_answer, answer_english, answer_spanish, source_file, source_type, is_official, status, is_annulled, raw_extract) VALUES ('ENEM2025-Q077','ENEM-2025',77,2025,1,'CH','Ciências Humanas','A','A',NULL,'2025_PV_impresso_D1_CD1.pdf','OFFICIAL_ENEM',true,'RAW_EXTRACT',false,'Questão 77 o objeto da lei penal. A obrigatoriedade ou necessidade de punir uma ação é proporcional à medida que tal ação tende Carro elétrico, uma miragem ecológica a perturbar a felicidade e à medida que a tendência do referido ato é perniciosa. A felicidade consiste naquilo que já vimos, ou seja, em desfrutar prazeres e em estar isento de dores. BENTHAM, J. Uma introdução aos princípios da moral e da legislação. São Paulo: Abril Cultural, 1974 (adaptado). Qual perspectiva de justiça emerge da relação, estabelecida no texto, entre punição e felicidade? A Aplicação de meios para atingir um fim. ') ON CONFLICT DO NOTHING;
