INSERT INTO public.questions (id, question_version, bank_number, exam_year, exam_day, area, discipline, official_answer, answer_english, answer_spanish, source_file, source_type, is_official, status, is_annulled, raw_extract) VALUES ('ENEM2025-Q095','ENEM-2025',95,2025,2,'CN','Ciências da Natureza','C',NULL,NULL,'2025_PV_impresso_D2_CD7.pdf','OFFICIAL_ENEM',true,'RAW_EXTRACT',false,'Questão 95 Questão 97 TEXTO I A produção de vacinas exige uma sequência de procedimentos, As mariposas além do cumprimento estrito de verificações de segurança. No esquema, estão demonstradas as etapas básicas realizadas As mariposa, quando chega o frio para a fabricação de uma vacina utilizando a tecnologia tradicional Fica dando volta em volta da lâmpida pra se esquentá. [sic] e o efeito dela no organismo. BARBOSA, A. Reviva: Adoniran Barbosa. São Paulo: Som Livre, 2002 (fragmento). TEXTO II As mariposas se aproximam das lâmpadas atraídas pela luz, pois, sendo basicamente criaturas noturnas, estão adaptadas a seguir o brilho da lua, em um processo conhecido como orientação transversal. Assim, o que o sambista Adoniran Barbosa, no Texto I, descreve não é a causa, mas sim uma das consequências possíveis dessa aproximação. De fato, o calor gerado pelas lâmpadas, sobretudo as incandescentes, pode aquecer as mariposas. HERTZBERG, R. Por que as mariposas são tão atraídas por luzes fortes? National Geographic, nov. 2020 (adaptado). Nesse contexto, o processo de transferência de calor para as mariposas que independe da presença de fluidos é a A reflexão. B refração. O antígeno utilizado na vacina causa um efeito protetor contra C irradiação. ') ON CONFLICT DO NOTHING;
