INSERT INTO public.questions (id, question_version, bank_number, exam_year, exam_day, area, discipline, official_answer, answer_english, answer_spanish, source_file, source_type, is_official, status, is_annulled, raw_extract) VALUES ('ENEM2025-Q099','ENEM-2025',99,2025,2,'CN','Ciências da Natureza','C',NULL,NULL,'2025_PV_impresso_D2_CD7.pdf','OFFICIAL_ENEM',true,'RAW_EXTRACT',false,'Questão 99 Questão 102 O monstro de gila, um lagarto encontrado em um deserto dos O sashimi (filé de peixe cru) de baiacu é uma iguaria muito Estados Unidos, apresenta adaptações à falta de alimento nesse apreciada no Japão. Entretanto, sua ingestão pode causar a ambiente. Esse lagarto possui um hormônio que controla os níveis morte por parada respiratória, pois esse peixe contém uma de açúcar em seu próprio sangue. Foi observado que esse hormônio potente neurotoxina termoestável, a tetrodotoxina, que é também controla os níveis de açúcar no sangue de pessoas diabéticas. produzida e armazenada nas gônadas e vísceras. RUSSELL, C. Ozempic e outros remédios inspirados em veneno de animais. Que ação poderia evitar essa intoxicação? Disponível em: www.bbc.com. Acesso em: 6 dez. 2024 (adaptado). A Criar os peixes em cativeiro. Considerando que animais de um mesmo grupo taxonômico B Realizar a pesca com redes. podem apresentar características adaptativas semelhantes em C Consumir peixes cozidos ou fritos. ambientes similares, onde seria mais provável encontrar lagartos com essas características no território brasileiro? ') ON CONFLICT DO NOTHING;
