INSERT INTO public.questions (id, question_version, bank_number, exam_year, exam_day, area, discipline, official_answer, answer_english, answer_spanish, source_file, source_type, is_official, status, is_annulled, raw_extract) VALUES ('ENEM2025-Q101','ENEM-2025',101,2025,2,'CN','Ciências da Natureza','A',NULL,NULL,'2025_PV_impresso_D2_CD7.pdf','OFFICIAL_ENEM',true,'RAW_EXTRACT',false,'Questão 101 50%, e a temperatura está agora cerca de 1,2 °C mais quente em comparação ao século XIX. O ritmo de aumento da temperatura Por que os olhos ficam vermelhos precisa diminuir se quisermos evitar as piores consequências das em algumas fotografias? mudanças climáticas. Cientistas afirmam que o aquecimento global Em fotos tiradas com câmeras fotográficas antigas, por precisa ser mantido em 1,5 °C até o ano 2100. No entanto, a menos vezes as pessoas aparecem com os olhos vermelhos. Isso que outras ações sejam tomadas, o planeta ainda pode aquecer ocorre porque a luz do flash da câmera incide diretamente mais de 2 °C até o final deste século. Na prática, os países precisam no globo ocular, sendo refletida por uma região repleta de enfrentar as mudanças climáticas com ações mitigadoras, que vasos sanguíneos. reduzam tanto as emissões quanto os níveis de CO2 na atmosfera. Disponível em: www.uol.com.br. Acesso em: 14 jun. 2017 (adaptado). Um guia rápido para entender as mudanças climáticas. ') ON CONFLICT DO NOTHING;
