INSERT INTO public.questions (id, question_version, bank_number, exam_year, exam_day, area, discipline, official_answer, answer_english, answer_spanish, source_file, source_type, is_official, status, is_annulled, raw_extract) VALUES ('ENEM2025-Q105','ENEM-2025',105,2025,2,'CN','Ciências da Natureza','E',NULL,NULL,'2025_PV_impresso_D2_CD7.pdf','OFFICIAL_ENEM',true,'RAW_EXTRACT',false,'Questão 105 As usinas termonucleares são aquelas que produzem energia elétrica a partir da geração de energia térmica proveniente das reações nucleares. Normalmente, essas usinas funcionam por meio de dois circuitos, denominados circuito primário (vaso de pressão, pressurizador e bomba) e circuito secundário (gerador de vapor, turbina, condensador, tanque de alimentação e bombas), além de um sistema de água de refrigeração, formado por uma bomba ligada a uma fonte hídrica natural. Durante a operação da usina, se o sistema de água de refrigeração funcionar de forma ineficiente pode causar poluição térmica, comprometendo a vida no ecossistema aquático. Disponível em: www.eletronuclear.gov.br. Acesso em: 29 nov. 2021 (adaptado). Para o ecossistema aquático, a ineficiência do sistema de água de refrigeração tem como consequência a A diminuição do pH. B liberação de gases poluentes. C contaminação por combustíveis. D liberação de elementos radioativos. E diminuição da solubilidade do gás oxigênio. Questão 106 No início do século XX, as fórmulas das substâncias eram representadas de modo diferente do atual. A figura apresenta uma fotografia bem antiga (1909) que registra uma aula de química ministrada em um colégio em Santos (SP). Um olhar mais atento permite identificar como os compostos químicos eram representados. O nitrogênio era chamado de azoto e representado pelo símbolo Az. Vê-se na lousa a equação representativa da adição do oxigênio atômico (O) ao monóxido de nitrogênio (AzO) com a formação de dióxido de nitrogênio (AzO2). Analogamente, o nitrato de sódio era representado por NaAzO3. Disponível em: www.novomilenio.inf.br. Acesso em: 29 ago. 2014 (adaptado). Em 1909, as representações das substâncias ácido nítrico e cloreto de cálcio, tendo por base essas informações e seguindo a mesma lógica, seriam, respectivamente: A HAzO3 e CaCl2 B HAz3O e Ca2Cl C H3AzO4 e CaCl D HAz3O e KCl2 E HAzO2 e KCl  CIÊNCIAS DA NATUREZA E SUAS TECNOLOGIAS | 2º DIA | CADERNO 7 | AZUL 5 P1_2_Dia_CNT_REG_7_Azul.indd 5 ') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, question_version, bank_number, exam_year, exam_day, area, discipline, official_answer, answer_english, answer_spanish, source_file, source_type, is_official, status, is_annulled, raw_extract) VALUES ('ENEM2025-Q106','ENEM-2025',106,2025,2,'CN','Ciências da Natureza','A',NULL,NULL,'2025_PV_impresso_D2_CD7.pdf','OFFICIAL_ENEM',true,'RAW_EXTRACT',false,'Questão 106 No início do século XX, as fórmulas das substâncias eram representadas de modo diferente do atual. A figura apresenta uma fotografia bem antiga (1909) que registra uma aula de química ministrada em um colégio em Santos (SP). Um olhar mais atento permite identificar como os compostos químicos eram representados. O nitrogênio era chamado de azoto e representado pelo símbolo Az. Vê-se na lousa a equação representativa da adição do oxigênio atômico (O) ao monóxido de nitrogênio (AzO) com a formação de dióxido de nitrogênio (AzO2). Analogamente, o nitrato de sódio era representado por NaAzO3. Disponível em: www.novomilenio.inf.br. Acesso em: 29 ago. 2014 (adaptado). Em 1909, as representações das substâncias ácido nítrico e cloreto de cálcio, tendo por base essas informações e seguindo a mesma lógica, seriam, respectivamente: A HAzO3 e CaCl2 B HAz3O e Ca2Cl C H3AzO4 e CaCl D HAz3O e KCl2 E HAzO2 e KCl  CIÊNCIAS DA NATUREZA E SUAS TECNOLOGIAS | 2º DIA | CADERNO 7 | AZUL 5 P1_2_Dia_CNT_REG_7_Azul.indd 5 25/07/2025 11:15:12 *020325AZ6*  Questão 107 Questão 108 A figura apresenta a herança genética de uma característica ') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, question_version, bank_number, exam_year, exam_day, area, discipline, official_answer, answer_english, answer_spanish, source_file, source_type, is_official, status, is_annulled, raw_extract) VALUES ('ENEM2025-Q107','ENEM-2025',107,2025,2,'CN','Ciências da Natureza','E',NULL,NULL,'2025_PV_impresso_D2_CD7.pdf','OFFICIAL_ENEM',true,'RAW_EXTRACT',false,'Questão 107 Questão 108 A figura apresenta a herança genética de uma característica Para transportar uma caixa do primeiro para o segundo a partir do cruzamento de insetos de uma mesma espécie. piso de uma construção, um trabalhador precisará arrasta-lá sobre um plano inclinado. O trabalhador começa a arrastar a caixa no primeiro piso, exercendo sobre ela uma força de grande intensidade, paralela ao seu deslocamento. Na medida em que a caixa sobe o plano inclinado, ele decide reduzir a força sobre ela, arrastando-a lentamente até chegar ao segundo piso. Considere que a caixa permanece em movimento nos encontros dos pisos com o plano inclinado, e que a rugosidade entre as superfícies permanece a mesma durante todo o percurso. ') ON CONFLICT DO NOTHING;
