INSERT INTO public.questions (id, question_version, bank_number, exam_year, exam_day, area, discipline, official_answer, answer_english, answer_spanish, source_file, source_type, is_official, status, is_annulled, raw_extract) VALUES ('ENEM2025-Q113','ENEM-2025',113,2025,2,'CN','Ciências da Natureza','B',NULL,NULL,'2025_PV_impresso_D2_CD7.pdf','OFFICIAL_ENEM',true,'RAW_EXTRACT',false,'Questão 113 Questão 114 A Figura 1 apresenta o esquema de um tubo de imagem em que A tirinha ilustra um processo físico em que uma onda sonora, um filamento, na posição A, libera elétrons por efeito termiônico. produzida pela Mônica, causa a quebra das taças de cristal. Esses elétrons formam um feixe estreito, que é acelerado por O fenômeno ondulatório que provoca a quebra das taças só é campos elétricos em direção à parte interna da tela. Nesse possível em razão de uma característica da voz produzida pela caminho, o feixe de elétrons passa por outro campo elétrico, na Mônica naquele momento, que, diferentemente do que sugere região B, atingindo, em seguida, a parte interna da tela do tubo, a tirinha, não está relacionada à sua intensidade. a qual é recoberta por um material que emite luz ao receber o impacto dos elétrons. Disponível em: https://artedafisicapibid.blogspot.com. Acesso em: 23 nov. 2021 (adaptado). Esse fenômeno e a característica associada à voz da Mônica ') ON CONFLICT DO NOTHING;
