INSERT INTO public.questions (id, question_version, bank_number, exam_year, exam_day, area, discipline, official_answer, answer_english, answer_spanish, source_file, source_type, is_official, status, is_annulled, raw_extract) VALUES ('ENEM2025-Q115','ENEM-2025',115,2025,2,'CN','Ciências da Natureza','C',NULL,NULL,'2025_PV_impresso_D2_CD7.pdf','OFFICIAL_ENEM',true,'RAW_EXTRACT',false,'Questão 115 que é acelerado e, posteriormente, atinge um ponto da tela. Em uma aula prática de química orgânica, um professor O campo elétrico na região B apresenta a seguinte configuração: identificou os frascos de várias substâncias apenas por suas fórmulas moleculares. Em seguida, apresentou a representação tridimensional da molécula do borneol, um álcool secundário, conforme a figura. Ele explicou que, quando oxidado, o borneol dá origem à cânfora, uma cetona usada desde a Antiguidade como incenso e no preparo de medicamentos. Finalmente, o professor solicitou que os alunos identificassem o frasco contendo a substância cânfora. Figura 2 Grupo de Reelaboração do Ensino de Física. Física 3: eletromagnetismo. São Paulo: Edusp, 2000 (adaptado). Nessa situação, qual ponto da tela será atingido pelo feixe de elétrons? A1 B2 ') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, question_version, bank_number, exam_year, exam_day, area, discipline, official_answer, answer_english, answer_spanish, source_file, source_type, is_official, status, is_annulled, raw_extract) VALUES ('ENEM2025-Q116','ENEM-2025',116,2025,2,'CN','Ciências da Natureza','C',NULL,NULL,'2025_PV_impresso_D2_CD7.pdf','OFFICIAL_ENEM',true,'RAW_EXTRACT',false,'Questão 116 Questão 119 As cangas são ambientes resultantes da atuação, ao longo Em uma comunidade rural, os moradores utilizam uma de milhões de anos, de chuvas, enxurradas, calor e ventos em bomba-d’água alimentada por 100 V de tensão contínua, rochas ricas em ferro. São compostas por até 90% de óxidos podendo variar em até 5 V. Um eletrotécnico pretende instalar de ferro e contêm solos muito ácidos, rasos, com reduzidos placas fotovoltaicas para alimentar essa bomba. As placas são índices de fertilidade e temperaturas que atingem quase 70 °C idênticas e cada uma apresenta tensão de operação igual a na superfície. Ao contrário do que se imagina, esse tipo de 34 V com corrente de 7,5 A. Além disso, cada placa apresenta ambiente abriga comunidades de plantas e animais com elevado 40 V de tensão elétrica, quando em circuito aberto. Assim, número de espécies e distribuição restrita. considerando que a placa descrita é um gerador não ideal, em circuito aberto ela pode ser representada conforme a figura: CARMO, F. F. et al. Ilhas de ferro estratégicas para a conservação. Disponível em: http://cienciahoje.org.br. Acesso em: 2 dez. 2018 (adaptado). A seleção adaptativa nesses ambientes favorece a ocorrência ') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, question_version, bank_number, exam_year, exam_day, area, discipline, official_answer, answer_english, answer_spanish, source_file, source_type, is_official, status, is_annulled, raw_extract) VALUES ('ENEM2025-Q117','ENEM-2025',117,2025,2,'CN','Ciências da Natureza','D',NULL,NULL,'2025_PV_impresso_D2_CD7.pdf','OFFICIAL_ENEM',true,'RAW_EXTRACT',false,'Questão 117 eletrotécnico é: Para a produção de titânio metálico ou dióxido de titânio puros, é necessário fazer a cloração do minério que contém dióxido de titânio, com o objetivo de separar esse óxido de outras substâncias presentes no minério. A principal reação A química de cloração é representada por: TiO2 (s) + 2 Cl2 (g) TiCl4 (g) + O2 (g) ΔH = +175 kJ/mol Depois da cloração, o tetracloreto de titânio é condensado e convertido, novamente, a dióxido de titânio. Após o sistema atingir o equilíbrio químico, como a formação B do TiCl4 pode ser favorecida? A Aumentando a pressão total do sistema. B Diminuindo a temperatura do sistema. C Aumentando a pressão parcial de O2. D Aumentando a pressão parcial de Cl2. C E Variando a quantidade de TiO2. Questão 118 A laje de um depósito de bebidas tem 50 m2 de área útil de armazenamento e foi projetada para suportar pressões de até 104 Pa. O gerente do estabelecimento pretende armazenar um produto cuja densidade é 1 250 kg/m3. Considere a aceleração D da gravidade igual a 10 m/s2. A altura máxima, em metro, de empilhamento do produto que essa laje é capaz de suportar é A 0,16 m. B 0,50 m. E C 0,80 m. D 1,60 m. E 8,00 m.  CIÊNCIAS DA NATUREZA E SUAS TECNOLOGIAS | 2º DIA | CADERNO 7 | AZUL ') ON CONFLICT DO NOTHING;
