INSERT INTO public.questions (id, question_version, bank_number, exam_year, exam_day, area, discipline, official_answer, answer_english, answer_spanish, source_file, source_type, is_official, status, is_annulled, raw_extract) VALUES ('ENEM2025-Q125','ENEM-2025',125,2025,2,'CN','Ciências da Natureza','B',NULL,NULL,'2025_PV_impresso_D2_CD7.pdf','OFFICIAL_ENEM',true,'RAW_EXTRACT',false,'Questão 125 Apaixonada por culinária e química, uma chefe de cozinha Durante a ação do vento, a velocidade v que o piloto deve calculou que, para promover o crescimento adequado da estabelecer em relação ao ar para que o avião chegue à posição massa durante o cozimento de um bolo a 180 °C (453 K) e esperada no tempo indicado tem as componentes 1,00 atm, ela precisaria utilizar uma quantidade de fermento A 230 km/h para Leste, 180 km/h para Sul e 9 km/h para baixo. químico suficiente para produzir um volume de gás igual a B 230 km/h para Leste, 180 km/h para Norte e 9 km/h para cima. 4,00 L. Com esse objetivo, ela escolheu utilizar o bicarbonato de C 200 km/h para Oeste, 200 km/h para Norte e 10 km/h para cima. amônio, um composto que, sob aquecimento, degrada-se em D 170 km/h para Leste, 220 km/h para Norte e 11 km/h para cima. três gases distintos, que são os responsáveis pelo crescimento E 170 km/h para Leste, 180 km/h para Norte e 11 km/h para cima. da massa. A decomposição do bicarbonato de amônio ocorre conforme a equação química apresentada e, nas condições do cozimento, seu rendimento é de 80%. NH4HCO3 (s) → NH3 (g) + CO2 (g) + H2O (g) Considere que a mistura dos gases se comporta como gás ideal nas condições de cozimento utilizadas pela chefe. Dados: Massa molar do NH 4 HCO 3 = 79 g ⋅ mol −1 e R = 0,082 atm ⋅ L ⋅ mol −1 ⋅ K −1. A massa, em grama, de bicarbonato de amônio que ela deve utilizar é mais próxima de A 2,3 g. B 3,5 g. C 5,9 g. D 6,8 g. E 8,9 g. ENEM2025ENEM2025ENEM2025ENEM2025ENEM2025ENEM2025ENEM2025ENEM2025ENEM2025ENEM2025ENEM2025ENEM2025ENEM2025ENEN2025ENEM2025ENEM20