INSERT INTO public.questions (id, question_version, bank_number, exam_year, exam_day, area, discipline, official_answer, answer_english, answer_spanish, source_file, source_type, is_official, status, is_annulled, raw_extract) VALUES ('ENEM2025-Q127','ENEM-2025',127,2025,2,'CN','Ciências da Natureza','C',NULL,NULL,'2025_PV_impresso_D2_CD7.pdf','OFFICIAL_ENEM',true,'RAW_EXTRACT',false,'Questão 127 Questão 128 Nos processos de transformação e reciclagem de recursos A resistência de um fio de platina pode ser usada para naturais, as velocidades das reações químicas são estudadas pela medir temperaturas entre 0 °C e 100 °C e já foi utilizada como cinética química. Uma reação A → B é realizada na presença referência para a escala internacional de temperatura. Para e na ausência de uma enzima, com todas as demais condições um sensor feito de platina, a relação entre a resistência e permanecendo inalteradas. Considere que, no gráfico da a temperatura pode ser descrita por uma equação do tipo variação de energia ao longo dessa reação, a linha contínua R(T) = A + BT, em que T é a temperatura e A e B são constantes. representa o avanço da reação na ausência da enzima, e a linha O gráfico apresenta a dependência da resistência em função pontilhada, na presença da enzima. da temperatura para cinco diferentes sensores. O gráfico que representa a situação descrita é: A B Os sensores que apresentam maior sensibilidade são A 1 e 2. ') ON CONFLICT DO NOTHING;
