INSERT INTO public.questions (id, question_version, bank_number, exam_year, exam_day, area, discipline, official_answer, answer_english, answer_spanish, source_file, source_type, is_official, status, is_annulled, raw_extract) VALUES ('ENEM2025-Q133','ENEM-2025',133,2025,2,'CN','Ciências da Natureza','A',NULL,NULL,'2025_PV_impresso_D2_CD7.pdf','OFFICIAL_ENEM',true,'RAW_EXTRACT',false,'Questão 133 Questão 134 O despejo acidental de óleo nos oceanos tem ocasionado Alguns hormônios sexuais têm ganhado notável atenção nos incontáveis prejuízos à vida marinha e à economia de regiões últimos anos por suas concentrações cada vez maiores no solo e costeiras. Métodos tradicionais de tratamento do despejo geram na água em todo o mundo. O motivo da preocupação é porque, resíduos de difícil descarte e nem sempre são eficazes. Por isso, em níveis poluentes, eles têm sido associados ao câncer de mama pesquisadores desenvolveram um filtro capaz de separar óleo e ao câncer de próstata, além de perturbarem a fisiologia dos e água. O dispositivo é montado sobre uma malha de aço com peixes, podendo, ainda, afetarem o desenvolvimento reprodutivo uma sequência de camadas. A primeira camada é formada de animais domésticos e selvagens. Assim, o descarte inadequado por um polímero de carga positiva, a segunda é composta por desses hormônios representa uma séria ameaça ao solo, plantas, nanopartículas de sílica (SiO2), a terceira é formada pelo mesmo recursos hídricos e humanos. De baixa polaridade, eles apresentam polímero e a última é um surfactante, conforme apresentado uma solubilidade pequena e variável em água, dependendo dos na figura. ') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, question_version, bank_number, exam_year, exam_day, area, discipline, official_answer, answer_english, answer_spanish, source_file, source_type, is_official, status, is_annulled, raw_extract) VALUES ('ENEM2025-Q134','ENEM-2025',134,2025,2,'CN','Ciências da Natureza','B',NULL,NULL,'2025_PV_impresso_D2_CD7.pdf','OFFICIAL_ENEM',true,'RAW_EXTRACT',false,'Questão 134 O despejo acidental de óleo nos oceanos tem ocasionado Alguns hormônios sexuais têm ganhado notável atenção nos incontáveis prejuízos à vida marinha e à economia de regiões últimos anos por suas concentrações cada vez maiores no solo e costeiras. Métodos tradicionais de tratamento do despejo geram na água em todo o mundo. O motivo da preocupação é porque, resíduos de difícil descarte e nem sempre são eficazes. Por isso, em níveis poluentes, eles têm sido associados ao câncer de mama pesquisadores desenvolveram um filtro capaz de separar óleo e ao câncer de próstata, além de perturbarem a fisiologia dos e água. O dispositivo é montado sobre uma malha de aço com peixes, podendo, ainda, afetarem o desenvolvimento reprodutivo uma sequência de camadas. A primeira camada é formada de animais domésticos e selvagens. Assim, o descarte inadequado por um polímero de carga positiva, a segunda é composta por desses hormônios representa uma séria ameaça ao solo, plantas, nanopartículas de sílica (SiO2), a terceira é formada pelo mesmo recursos hídricos e humanos. De baixa polaridade, eles apresentam polímero e a última é um surfactante, conforme apresentado uma solubilidade pequena e variável em água, dependendo dos na figura. grupos presen') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, question_version, bank_number, exam_year, exam_day, area, discipline, official_answer, answer_english, answer_spanish, source_file, source_type, is_official, status, is_annulled, raw_extract) VALUES ('ENEM2025-Q135','ENEM-2025',135,2025,2,'CN','Ciências da Natureza','A',NULL,NULL,'2025_PV_impresso_D2_CD7.pdf','OFFICIAL_ENEM',true,'RAW_EXTRACT',false,'Questão 135 Os espectros de fotoluminescência do sensor no início e no final do tratamento estão esboçados no gráfico: A icterícia é uma doença que acomete recém-nascidos e pode ser tratada com um método de fototerapia conhecido como banho de luz, que consiste na exposição do recém-nascido a uma fonte luminosa equipada com LEDs azuis. Para o monitoramento da dosagem dessa radiação, é utilizada a resposta óptica de um sensor constituído de materiais orgânicos que luminescem quando A expostos à luz azul. Com o passar do tempo, essa radiação oxida os materiais do sensor, alterando sua coloração de vermelho-laranja para verde, o que indica o final do tratamento. O gráfico apresenta o espectro de fotoluminescência do sensor em função do comprimento de onda da luz emitida no início do tratamento, quando o sensor, colado na fralda do bebê (Figura 1), luminesce na região do vermelho-laranja (∼600 nm). A Figura 2 apresenta a evolução da coloração do sensor, mostrando que a frequência da luz emitida por ele aumenta em função do tempo de exposição à luz azul. B C D E SILVA, M. M. et al. Fabricação de sensor orgânico flexível para aplicação em terapia com luz azul. Tecnol. Metal. Mater. Miner., n. 3, jul.-set. 2011 (adaptado). ') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, question_version, bank_number, exam_year, exam_day, area, discipline, official_answer, answer_english, answer_spanish, source_file, source_type, is_official, status, is_annulled, raw_extract) VALUES ('ENEM2025-Q136','ENEM-2025',136,2025,2,'MT','Matemática','C',NULL,NULL,'2025_PV_impresso_D2_CD7.pdf','OFFICIAL_ENEM',true,'RAW_EXTRACT',false,'Questão 136 Uma pessoa pretende instalar um kit de gás natural veicular (GNV) em seu carro. Na loja que escolheu para realizar a compra e instalação desse kit, havia cinco modelos de cilindro para armazenamento do gás, cujas capacidades, em metro cúbico, eram, respectivamente: 10, 14, 17, 21 e 25. O preço do cilindro é proporcional à sua capacidade. Esse carro rodará 30 km diariamente, 7 dias por semana, e o consumo do GNV é de 1 m3 a cada 13 km rodados. A pessoa escolherá o modelo de cilindro de menor preço e que garanta apenas um abastecimento semanal. Nessas condições, qual será a capacidade, em metro cúbico, do cilindro escolhido por essa pessoa? A 10 B 14 C 17 D 21 E 25 Questão 137 A reportagem de uma revista abordou o uso de redes sociais pelos internautas brasileiros. Alguns dos dados apurados pela reportagem estão apresentados no infográfico. Perfil dos brasileiros nas redes sociais Disponível em: http://revistagalileu.globo.com. Acesso em: 22 out. 2015 (adaptado). Segundo os dados do infográfico, ao se escolher aleatoriamente um internauta brasileiro no período ao qual se refere a reportagem, a probabilidade de ele ser um homem que acessa alguma rede social é 30 A 90 36 B 100 40 C 100 40 D 90 46 E 90  16 MATEMÁTICA E SUAS TECNOLOGIAS | 2º DIA | CADERNO 7 | AZUL 020325AZ.indb 16 24/07/2025 19:03:13 ') ON CONFLICT DO NOTHING;
