INSERT INTO public.questions (id, question_version, bank_number, exam_year, exam_day, area, discipline, official_answer, answer_english, answer_spanish, source_file, source_type, is_official, status, is_annulled, raw_extract) VALUES ('ENEM2025-Q152','ENEM-2025',152,2025,2,'MT','Matemática','D',NULL,NULL,'2025_PV_impresso_D2_CD7.pdf','OFFICIAL_ENEM',true,'RAW_EXTRACT',false,'Questão 152 Quantos vértices tem esse poliedro? Quatro candidatos se apresentaram para realizar a prova de A 21 um concurso. Antes de iniciar a prova, os celulares dos quatro candidatos foram recolhidos pelo aplicador, que os guardou, B 25 cada um, dentro de um envelope preto. Ao término da prova, C 55 o aplicador devolveu os quatro envelopes com os celulares aos D 80 quatro candidatos, de maneira aleatória, já que não havia feito E 110 a identificação dos envelopes. Questão 150 A probabilidade de que todos os candidatos tenham recebido Uma fábrica de tijolos ecológicos com 3 funcionários, de volta os envelopes com os seus respectivos celulares é cada um trabalhando 6 horas diárias, produz 720 unidades 1 por dia. Para atender ao crescimento da demanda por esse A ') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, question_version, bank_number, exam_year, exam_day, area, discipline, official_answer, answer_english, answer_spanish, source_file, source_type, is_official, status, is_annulled, raw_extract) VALUES ('ENEM2025-Q153','ENEM-2025',153,2025,2,'MT','Matemática','A',NULL,NULL,'2025_PV_impresso_D2_CD7.pdf','OFFICIAL_ENEM',true,'RAW_EXTRACT',false,'Questão 153 Questão 154 Em um jogo digital, há três personagens: um herói e dois Uma livraria comercializa livros dos seguintes gêneros vilões. A programação é feita de tal forma que o herói sempre literários: ficção científica, autoajuda, romance e biografia. será atacado pelo vilão que estiver mais próximo dele. Uma das O gráfico apresenta o estoque dos livros que essa livraria tem, maneiras de “confundir” os vilões é movimentar o herói por por gênero literário e por nacionalidade do autor, bem como a trajetórias que o mantenha equidistante dos vilões, gerando demanda por gênero literário, obtida por meio de uma enquete indefinição entre eles e, com isso, não sendo atacado. feita com seus clientes habituais. Para a programação de uma das etapas desse jogo, Estoque e demanda por livros o programador considerou, no plano cartesiano, o quadrado STUV como a região de movimentação dos personagens, onde V e T representam as posições fixas dos vilões, e S, a posição inicial do herói, como apresentado na figura. O gerente da livraria fará a encomenda de novos exemplares somente do gênero cuja quantidade em estoque seja insuficiente ') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, question_version, bank_number, exam_year, exam_day, area, discipline, official_answer, answer_english, answer_spanish, source_file, source_type, is_official, status, is_annulled, raw_extract) VALUES ('ENEM2025-Q154','ENEM-2025',154,2025,2,'MT','Matemática','C',NULL,NULL,'2025_PV_impresso_D2_CD7.pdf','OFFICIAL_ENEM',true,'RAW_EXTRACT',false,'Questão 154 Em um jogo digital, há três personagens: um herói e dois Uma livraria comercializa livros dos seguintes gêneros vilões. A programação é feita de tal forma que o herói sempre literários: ficção científica, autoajuda, romance e biografia. será atacado pelo vilão que estiver mais próximo dele. Uma das O gráfico apresenta o estoque dos livros que essa livraria tem, maneiras de “confundir” os vilões é movimentar o herói por por gênero literário e por nacionalidade do autor, bem como a trajetórias que o mantenha equidistante dos vilões, gerando demanda por gênero literário, obtida por meio de uma enquete indefinição entre eles e, com isso, não sendo atacado. feita com seus clientes habituais. Para a programação de uma das etapas desse jogo, Estoque e demanda por livros o programador considerou, no plano cartesiano, o quadrado STUV como a região de movimentação dos personagens, onde V e T representam as posições fixas dos vilões, e S, a posição inicial do herói, como apresentado na figura. O gerente da livraria fará a encomenda de novos exemplares somente do gênero cuja quantidade em estoque seja insuficiente para atender a demanda constatada pela enquete. ') ON CONFLICT DO NOTHING;
