INSERT INTO public.questions (id, question_version, bank_number, exam_year, exam_day, area, discipline, official_answer, answer_english, answer_spanish, source_file, source_type, is_official, status, is_annulled, raw_extract) VALUES ('ENEM2025-Q164','ENEM-2025',164,2025,2,'MT','Matemática','A',NULL,NULL,'2025_PV_impresso_D2_CD7.pdf','OFFICIAL_ENEM',true,'RAW_EXTRACT',false,'Questão 164 Em uma escola, todos os estudantes do ensino médio O dono de uma embarcação deve partir do ponto P e praticam uma das três modalidades esportivas oferecidas chegar ao ponto R por meio de dois deslocamentos lineares como atividade física, e cada um deles pratica somente uma e navegando a uma velocidade constante. Essa viagem será dessas atividades. Os gráficos trazem alguns dados relativos aos feita durante a noite, e como ele dispõe somente de uma quantitativos de estudantes que praticam essas modalidades bússola e de um relógio, planejou sua rota da seguinte forma: esportivas nessa escola, apesar de algumas quantidades não 1º – partir do ponto P na direção 110 e navegar por 4 horas, terem sido informadas. alcançando um ponto Q; 2º – partir do ponto Q na direção 90 e navegar por 2 horas, alcançando o ponto de destino R. No entanto, ao direcionar o barco para o primeiro deslocamento, o fez na direção 340, em vez de 110. Com isso, ') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, question_version, bank_number, exam_year, exam_day, area, discipline, official_answer, answer_english, answer_spanish, source_file, source_type, is_official, status, is_annulled, raw_extract) VALUES ('ENEM2025-Q165','ENEM-2025',165,2025,2,'MT','Matemática','D',NULL,NULL,'2025_PV_impresso_D2_CD7.pdf','OFFICIAL_ENEM',true,'RAW_EXTRACT',false,'Questão 165 Em um estudo clínico, 55 mulheres foram distribuídas, aleatoriamente, em 5 grupos de 11 pessoas. Para testar uma nova medicação, será escolhido um grupo no qual a maioria das mulheres tenham idades entre 20 e 30 anos. Os demais grupos tomarão placebo ou medicações já existentes no mercado. O quadro, parcialmente preenchido, informa alguns dados relativos às idades das mulheres desses grupos. Grupos Menor idade Maior idade Média Mediana Moda Desvio padrão 1 25 10 2 25 9 3 25 4 25 1 5 20 35 Mesmo com o quadro incompleto, foi possível selecionar um desses grupos porque, apenas com os dados apresentados no quadro, foi identificado um grupo que, certamente, atendia ao critério de escolha. O grupo escolhido foi o A 1. B 2. C 3. D 4. E 5. Questão 166 Pace é um termo usado por um corredor para denominar o seu ritmo médio em uma corrida. Representa o tempo médio, em segundo, que esse corredor leva para percorrer 1 km. O esquema apresenta o tempo, em segundo, que um corredor levou para cruzar as marcas que definem os quatro primeiros trechos de 1 km, em uma corrida de 5 km, e o ') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, question_version, bank_number, exam_year, exam_day, area, discipline, official_answer, answer_english, answer_spanish, source_file, source_type, is_official, status, is_annulled, raw_extract) VALUES ('ENEM2025-Q166','ENEM-2025',166,2025,2,'MT','Matemática','E',NULL,NULL,'2025_PV_impresso_D2_CD7.pdf','OFFICIAL_ENEM',true,'RAW_EXTRACT',false,'Questão 166 Pace é um termo usado por um corredor para denominar o seu ritmo médio em uma corrida. Representa o tempo médio, em segundo, que esse corredor leva para percorrer 1 km. O esquema apresenta o tempo, em segundo, que um corredor levou para cruzar as marcas que definem os quatro primeiros trechos de 1 km, em uma corrida de 5 km, e o tempo gasto para percorrer cada trecho de 1 km. O melhor pace que esse corredor alcançou em corridas de 5 km foi 281 s/km. Para que consiga repetir nessa corrida seu melhor pace em corridas de 5 km, seu tempo, no 5º trecho, deve ser quantos segundos menor do que o que ele gastou para percorrer o 4º trecho? A1 B2 C8 D9 E 15  26 MATEMÁTICA E SUAS TECNOLOGIAS | 2º DIA | CADERNO 7 | AZUL 020325AZ.indb 26 24/07/2025 19:03:39 *020325AZ27*  Questão 167 Uma pessoa tem um carro bicombustível, que funciona a gás natural veicular (GNV) e a gasolina. O rendimento do carro, medido em km/m³, no caso do gás, ou medido em km/L, no caso da gasolina, depende, entre outros fatores, da velocidade, em km/h, em que o carro trafega. Essa relação está em conformidade com estes gráficos. Durante um feriado, essa pessoa realizou uma viagem de 240 km. Para obter uma estimativa de gasto de combustível, assuma que em todo o trajeto se') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, question_version, bank_number, exam_year, exam_day, area, discipline, official_answer, answer_english, answer_spanish, source_file, source_type, is_official, status, is_annulled, raw_extract) VALUES ('ENEM2025-Q167','ENEM-2025',167,2025,2,'MT','Matemática','D',NULL,NULL,'2025_PV_impresso_D2_CD7.pdf','OFFICIAL_ENEM',true,'RAW_EXTRACT',false,'Questão 167 Uma pessoa tem um carro bicombustível, que funciona a gás natural veicular (GNV) e a gasolina. O rendimento do carro, medido em km/m³, no caso do gás, ou medido em km/L, no caso da gasolina, depende, entre outros fatores, da velocidade, em km/h, em que o carro trafega. Essa relação está em conformidade com estes gráficos. Durante um feriado, essa pessoa realizou uma viagem de 240 km. Para obter uma estimativa de gasto de combustível, assuma que em todo o trajeto se manteve uma velocidade constante de 60 km/h. Considere que, durante metade do caminho, foi utilizado apenas GNV e, na outra metade, apenas gasolina. O que foi pago pelo metro cúbico de GNV e pelo litro de gasolina correspondeu, respectivamente, a R$ 2,00 e a R$ 3,00. Qual foi a diferença, em real, entre os gastos totais com gasolina e com GNV? A4 B8 C 14 D 21 E 30 Questão 168 Em um país, a primeira etapa para obtenção da carteira de motorista é a contratação de três produtos: • pacote com 20 aulas teóricas; • pacote com 10 aulas práticas; • aluguel do veículo para realização das aulas práticas. Uma pessoa que pretende obter a carteira de motorista pesquisou o valor do aluguel do veículo e os valores de cada aula teórica e de cada aula prática em três autoescolas. O quadro apresenta esses valores. Autoescola Valor de cada aula teórica (R$) Valor de cada aula prática (R$) Aluguel do veículo (R$) I 10 80 400 II 30 50 200 III 20 40 400 Ela contratará os três produtos numa mesma autoescola de modo que o custo total nessa primeira etapa seja o menor possível. A autoescola que será contratada é a A I, com o custo total de R$ 1 400,00. B II, com o custo total de R$ 280,00. C II, com o custo total de R$ 1 300,00. D III, com o custo total de R$ 460,00. E III, com o custo total de R$ 1 200,00. ENEM2025ENEM2025ENEM2025EN') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, question_version, bank_number, exam_year, exam_day, area, discipline, official_answer, answer_english, answer_spanish, source_file, source_type, is_official, status, is_annulled, raw_extract) VALUES ('ENEM2025-Q168','ENEM-2025',168,2025,2,'MT','Matemática','E',NULL,NULL,'2025_PV_impresso_D2_CD7.pdf','OFFICIAL_ENEM',true,'RAW_EXTRACT',false,'Questão 168 Em um país, a primeira etapa para obtenção da carteira de motorista é a contratação de três produtos: • pacote com 20 aulas teóricas; • pacote com 10 aulas práticas; • aluguel do veículo para realização das aulas práticas. Uma pessoa que pretende obter a carteira de motorista pesquisou o valor do aluguel do veículo e os valores de cada aula teórica e de cada aula prática em três autoescolas. O quadro apresenta esses valores. Autoescola Valor de cada aula teórica (R$) Valor de cada aula prática (R$) Aluguel do veículo (R$) I 10 80 400 II 30 50 200 III 20 40 400 Ela contratará os três produtos numa mesma autoescola de modo que o custo total nessa primeira etapa seja o menor possível. A autoescola que será contratada é a A I, com o custo total de R$ 1 400,00. B II, com o custo total de R$ 280,00. C II, com o custo total de R$ 1 300,00. D III, com o custo total de R$ 460,00. E III, com o custo total de R$ 1 200,00.  MATEMÁTICA E SUAS TECNOLOGIAS | 2º DIA | CADERNO 7 | AZUL 27 020325AZ.indb 27 ') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, question_version, bank_number, exam_year, exam_day, area, discipline, official_answer, answer_english, answer_spanish, source_file, source_type, is_official, status, is_annulled, raw_extract) VALUES ('ENEM2025-Q169','ENEM-2025',169,2025,2,'MT','Matemática','A',NULL,NULL,'2025_PV_impresso_D2_CD7.pdf','OFFICIAL_ENEM',true,'RAW_EXTRACT',false,'Questão 169 A produtividade de soja em uma área cultivada é a média da quantidade de sacas de 50 quilogramas que são produzidas por hectare. O quadro apresenta a área cultivada e a produtividade de soja em certa propriedade, ao longo de cinco safras, com períodos de um ano, de 2011 a 2016. Safra 11-12 12-13 13-14 14-15 15-16 Área cultivada (hectare) 200 220 250 250 200 Produtividade (sacas de 50 kg por hectare) 40 30 45 45 50 O gráfico de linhas que representa a produção de soja dessa propriedade, em tonelada, nessas cinco safras é A D B E C  28 MATEMÁTICA E SUAS TECNOLOGIAS | 2º DIA | CADERNO 7 | AZUL 020325AZ.indb 28 ') ON CONFLICT DO NOTHING;
