INSERT INTO public.questions (id, question_version, bank_number, exam_year, exam_day, area, discipline, official_answer, answer_english, answer_spanish, source_file, source_type, is_official, status, is_annulled, raw_extract) VALUES ('ENEM2025-Q172','ENEM-2025',172,2025,2,'MT','Matemática','A',NULL,NULL,'2025_PV_impresso_D2_CD7.pdf','OFFICIAL_ENEM',true,'RAW_EXTRACT',false,'Questão 172 Um empresário utiliza máquinas cuja pressão interna P, em atmosfera, depende do tempo contínuo de utilização t, em hora, e de um parâmetro positivo K, que define o modelo da máquina, segundo a expressão: P = 4 ⋅ log[−K ⋅ (t + 1) ⋅ (t − 19)] O fabricante dessas máquinas recomenda ao usuário que a pressão interna desse tipo de máquina não ultrapasse 10 atmosferas durante seu funcionamento. O empresário pretende comprar novas máquinas desse tipo que deverão funcionar, diariamente, por um período contínuo de 10 horas. Para isso, precisa definir o modelo de ') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, question_version, bank_number, exam_year, exam_day, area, discipline, official_answer, answer_english, answer_spanish, source_file, source_type, is_official, status, is_annulled, raw_extract) VALUES ('ENEM2025-Q173','ENEM-2025',173,2025,2,'MT','Matemática','A',NULL,NULL,'2025_PV_impresso_D2_CD7.pdf','OFFICIAL_ENEM',true,'RAW_EXTRACT',false,'Questão 173 Questão 174 Em uma cidade, será construído um túnel que atravessa uma Um carro que custa 60 mil reais é comercializado por uma montanha para facilitar o trânsito de automóveis e bicicletas. revendedora que oferece duas opções de pagamento, todas Dois projetos foram elaborados e os esquemas com as vistas sem entrada e sem juros: frontais desses projetos são apresentados na figura. • opção 1: pagamento em n parcelas iguais; • opção 2: pagamento em 6 parcelas a mais do que na opção 1 e, com isso, o valor de cada parcela se torna R$ 500,00 menor do que o valor da parcela na opção 1. Nas duas opções de pagamento, o valor total a ser pago pelo carro é o mesmo. Qual é a quantidade n de parcelas contidas na opção 1 de ') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, question_version, bank_number, exam_year, exam_day, area, discipline, official_answer, answer_english, answer_spanish, source_file, source_type, is_official, status, is_annulled, raw_extract) VALUES ('ENEM2025-Q174','ENEM-2025',174,2025,2,'MT','Matemática','Anulado',NULL,NULL,'2025_PV_impresso_D2_CD7.pdf','OFFICIAL_ENEM',true,'RAW_EXTRACT',true,'Questão 174 Em uma cidade, será construído um túnel que atravessa uma Um carro que custa 60 mil reais é comercializado por uma montanha para facilitar o trânsito de automóveis e bicicletas. revendedora que oferece duas opções de pagamento, todas Dois projetos foram elaborados e os esquemas com as vistas sem entrada e sem juros: frontais desses projetos são apresentados na figura. • opção 1: pagamento em n parcelas iguais; • opção 2: pagamento em 6 parcelas a mais do que na opção 1 e, com isso, o valor de cada parcela se torna R$ 500,00 menor do que o valor da parcela na opção 1. Nas duas opções de pagamento, o valor total a ser pago pelo carro é o mesmo. Qual é a quantidade n de parcelas contidas na opção 1 de pagamento? ') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, question_version, bank_number, exam_year, exam_day, area, discipline, official_answer, answer_english, answer_spanish, source_file, source_type, is_official, status, is_annulled, raw_extract) VALUES ('ENEM2025-Q175','ENEM-2025',175,2025,2,'MT','Matemática','C',NULL,NULL,'2025_PV_impresso_D2_CD7.pdf','OFFICIAL_ENEM',true,'RAW_EXTRACT',false,'Questão 175 Um pai comprou oito presentes diferentes (dentre os quais, uma bicicleta e um celular) para dar a seus três filhos. Ele pretende distribuir os presentes de modo que o filho mais velho e o mais novo recebam três presentes cada um, e o do meio receba os dois presentes restantes. O mais velho ganhará, entre seus presentes, ou uma bicicleta ou um celular, mas não ambos. De quantas maneiras distintas a distribuição dos presentes pode ser feita? O Projeto 1 conta com dois túneis, um exclusivo para A 36 bicicletas e o outro, para automóveis. O Projeto 2 conta com B 53 um único túnel, com espaços reservados para o trânsito exclusivo ') ON CONFLICT DO NOTHING;
INSERT INTO public.questions (id, question_version, bank_number, exam_year, exam_day, area, discipline, official_answer, answer_english, answer_spanish, source_file, source_type, is_official, status, is_annulled, raw_extract) VALUES ('ENEM2025-Q176','ENEM-2025',176,2025,2,'MT','Matemática','C',NULL,NULL,'2025_PV_impresso_D2_CD7.pdf','OFFICIAL_ENEM',true,'RAW_EXTRACT',false,'Questão 176 O projeto a ser aprovado será aquele que apresentar a A final de um campeonato de futebol foi disputada em 2 tempos menor área da seção transversal, pois implicará menor volume regulamentares, de 45 minutos cada, sem acréscimos, com uma de material retirado da montanha. prorrogação de 30 minutos, também sem acréscimos. Um jogador Considere 3 como aproximação para p e desconsidere as entrou no início do segundo tempo, com um equipamento para espessuras das muretas. medir a distância percorrida durante sua participação no jogo. Ao final do segundo tempo regulamentar, esse jogador havia O projeto a ser aprovado é percorrido 4,5 km. Ele manteve na prorrogação a mesma velocidade A o 1, pois apresenta área de seção transversal medindo média que havia mantido no segundo tempo regulamentar. 67,5 m2. A distância percorrida por esse jogador durante sua participação B o 2, pois apresenta área de seção transversal medindo na partida, em quilômetro, foi 121,5 m2. ') ON CONFLICT DO NOTHING;
