INSERT INTO public.questions (id, question_version, bank_number, exam_year, exam_day, area, discipline, official_answer, answer_english, answer_spanish, source_file, source_type, is_official, status, is_annulled, raw_extract) VALUES ('ENEM2025-Q178','ENEM-2025',178,2025,2,'MT','Matemática','E',NULL,NULL,'2025_PV_impresso_D2_CD7.pdf','OFFICIAL_ENEM',true,'RAW_EXTRACT',false,'Questão 178 Três dados cúbicos, com faces numeradas de 1 a 6, foram utilizados em um jogo. Artur escolheu dois dados, e João ficou com o terceiro. O jogo consiste em ambos lançarem seus dados, observarem os números nas faces voltadas para cima e compararem o maior número obtido por Artur com O desenvolvimento do jogo se dá em rodadas e, em todas o número obtido por João. Vence o jogador que obtiver o elas, cada jogador transfere e recebe uma quantidade de moedas, maior número. Em caso de empate, a vitória é de João. da seguinte maneira: O jogador que tem a maior probabilidade de vitória é • o jogador na posição 1 transfere 1 moeda para o jogador 2 na posição 2; A Artur, com probabilidade de • o jogador na posição 2 transfere 2 moedas para o jogador 3 na posição 3; • o jogador na posição 3 transfere 3 moedas para o jogador 4 B João, com probabilidade de na posição 4; ') ON CONFLICT DO NOTHING;
